def choose_move(observation):
    # Defensive defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)

    # Try to infer a safe move with simple robust rules across modes
    # Prefer staying in place if nothing obvious
    dx = 0
    dy = 0

    # Resource collection: move toward closest resource if available
    resources = observation.get("resources", [])
    if resources:
        try:
            # compute vector toward nearest resource
            rx, ry = max(resources, key=lambda p: -(abs(p[0]-x) + abs(p[1]-y)))
            if rx > x:
                dx = min(dx + 1, 1)
            elif rx < x:
                dx = max(dx - 1, -1)
            if ry > y:
                dy = min(dy + 1, 1)
            elif ry < y:
                dy = max(dy - 1, -1)
        except Exception:
            pass

    # If no resources or to add some exploration shift, bias toward center if available
    center_bias = observation.get("center_bias", (0, 0))
    if center_bias:
        cx, cy = center_bias
        if cx > x:
            dx = min(dx + 1, 1)
        elif cx < x:
            dx = max(dx - 1, -1)
        if cy > y:
            dy = min(dy + 1, 1)
        elif cy < y:
            dy = max(dy - 1, -1)

    # Pursing/evading heuristic: if there is an opponent, try to stay away modestly
    opponents = observation.get("opponents", [])
    if opponents:
        # choose the closest opponent
        try:
            ox, oy = min(opponents, key=lambda p: abs(p[0]-x) + abs(p[1]-y))
            if ox > x:
                dx = min(dx - 1,  -1)  # move left
            elif ox < x:
                dx = max(dx + 1, 1)   # move right
            if oy > y:
                dy = min(dy - 1,  -1)
            elif oy < y:
                dy = max(dy + 1, 1)
        except Exception:
            pass

    # Territory control: if there is a target tile to approach, bias toward it
    targets = observation.get("territory_targets", [])
    if targets:
        try:
            tx, ty = targets[0]
            if tx > x:
                dx = min(dx + 1, 1)
            elif tx < x:
                dx = max(dx - 1, -1)
            if ty > y:
                dy = min(dy + 1, 1)
            elif ty < y:
                dy = max(dy - 1, -1)
        except Exception:
            pass

    # Bound to -1, 0, 1
    dx = -1 if dx < -1 else 1 if dx > 1 else dx
    dy = -1 if dy < -1 else 1 if dy > 1 else dy

    return [dx, dy]

